def k_concatenation_max_sum(arr, k):
 mod=1000000007
 def kadane(values):
  best=current=0
  for value in values:current=max(0,current+value);best=max(best,current)
  return best
 if k==1:return kadane(arr)%mod
 return (kadane(arr*2)+max(0,sum(arr))*(k-2))%mod

